import { PrismaClient } from '@prisma/client';
import bcrypt from 'bcryptjs';
const prisma = new PrismaClient();
async function main() {
    console.log('Seeding initial data...');
    const hashedPassword = await bcrypt.hash('password123', 10);
    // Create default admin
    const admin = await prisma.user.upsert({
        where: { email: 'admin@hackclubvit.co' },
        update: { password: hashedPassword },
        create: {
            name: 'System Admin',
            email: 'admin@hackclubvit.co',
            password: hashedPassword,
            role: 'ADMIN',
            departments: ['CSE', 'ECE', 'DESIGN', 'MANAGEMENT']
        },
    });
    // Create a default Form
    const defaultForm = await prisma.form.upsert({
        where: { id: 1 },
        update: {},
        create: {
            id: 1,
            title: 'HackClub VIT General Recruitment',
            description: 'Standard recruitment application form for all departments.',
            status: 'PUBLISHED',
            published_at: new Date()
        }
    });
    // Create default form questions
    const questions = [
        { form_id: 1, question: 'Why do you want to join HackClub VIT?', type: 'PARAGRAPH', required: true },
        { form_id: 1, question: 'What is your primary tech stack?', type: 'TEXT', required: true },
        { form_id: 1, question: 'Are you available for weekend hackathons?', type: 'RADIO', required: true, options: ['Yes', 'No', 'Maybe'] }
    ];
    for (const q of questions) {
        const existing = await prisma.formQuestion.findFirst({
            where: { form_id: q.form_id, question: q.question }
        });
        if (!existing) {
            await prisma.formQuestion.create({
                data: {
                    form_id: q.form_id,
                    question: q.question,
                    type: q.type,
                    required: q.required,
                    options: q.options || []
                }
            });
        }
    }
    console.log('Seed completed successfully.');
    console.log('Admin credentials: admin@hackclubvit.co / password123');
}
main()
    .then(async () => {
    await prisma.$disconnect();
})
    .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
});

import express from 'express';
import cors from 'cors';
import cookieParser from 'cookie-parser';
import dotenv from 'dotenv';
import { router } from './router.js';
dotenv.config();
const app = express();
const port = process.env.PORT || 3001;
// Middlewares
app.use(express.json());
app.use(cookieParser());
const allowedOrigins = process.env.ALLOWED_ORIGIN
    ? process.env.ALLOWED_ORIGIN.split(',')
    : ['http://localhost:3000', 'https://recruitment.hackclubvit.co'];
app.use(cors({
    origin: function (origin, callback) {
        if (!origin || allowedOrigins.includes(origin)) {
            callback(null, true);
        }
        else {
            callback(new Error('Not allowed by CORS'));
        }
    },
    credentials: true,
}));
// Routes
app.use('/api', router);
// Error handling middleware
app.use((err, req, res, next) => {
    console.error('API Error:', err.message);
    if (err.message === 'Not allowed by CORS') {
        res.status(403).json({ error: 'CORS policy violation' });
    }
    else {
        res.status(500).json({ error: 'Internal server error' });
    }
});
app.listen(port, () => {
    console.log(`Independent API server running on port ${port}`);
});

import { SignJWT, jwtVerify } from "jose";
import prisma from "./db";
function getSecretKey() {
    if (process.env.NODE_ENV === "production" && !process.env.JWT_SECRET) {
        throw new Error("JWT_SECRET must be provided in production");
    }
    return process.env.JWT_SECRET || "development_secret_only";
}
const getEncodedKey = () => new TextEncoder().encode(getSecretKey());
export async function signToken(payload) {
    return new SignJWT(payload)
        .setProtectedHeader({ alg: "HS256" })
        .setIssuedAt()
        .setExpirationTime("7d")
        .sign(getEncodedKey());
}
export async function verifyToken(token = "") {
    try {
        const { payload } = await jwtVerify(token, getEncodedKey(), {
            algorithms: ["HS256"],
        });
        return payload;
    }
    catch (error) {
        return null;
    }
}
export async function getSession(req) {
    if (!req)
        return null;
    const token = req.cookies?.session;
    if (!token)
        return null;
    const payload = await verifyToken(token);
    if (!payload || !payload.id)
        return null;
    const user = await prisma.user.findUnique({
        where: { id: payload.id }
    });
    if (!user || !user.active)
        return null;
    return {
        id: user.id,
        role: user.role,
        departments: user.departments || []
    };
}

import prisma from "../../lib/db";
import { getSession } from "../../lib/auth";
import { logAudit } from "../../lib/audit";
import { createNotification } from "../../lib/notify";
import { z } from "zod";
export const GET = async (req, res) => {
    const params = req.params;
    try {
        const session = await getSession(req);
        if (!session) {
            return res.status(401).json({ error: "Unauthorized" });
        }
        const resolvedParams = req.params;
        const id = parseInt(resolvedParams.id, 10);
        let includeClause = {
            form: { include: { questions: true } }
        };
        if (session.role === "PANEL_MEMBER") {
            includeClause.candidate = {
                select: {
                    id: true,
                    name: true,
                    department: true,
                    registration_number: true
                }
            };
        }
        else {
            includeClause.candidate = true;
        }
        const application = await prisma.application.findUnique({
            where: { id },
            include: includeClause
        });
        if (!application) {
            return res.status(404).json({ error: "Application not found" });
        }
        // Authorization
        if (session.role === "RECRUITER") {
            if (!session.departments?.includes(application.candidate.department)) {
                return res.status(403).json({ error: "Forbidden" });
            }
        }
        if (session.role === "PANEL_MEMBER") {
            const hasAccess = await prisma.interview.findFirst({
                where: {
                    application_id: id,
                    assigned_members: { some: { user_id: session.id } }
                }
            });
            if (!hasAccess) {
                return res.status(403).json({ error: "Forbidden" });
            }
        }
        return res.status(200).json({ application });
    }
    catch (error) {
        console.error("Fetch application error:", error);
        return res.status(500).json({ error: "Internal server error" });
    }
};
const updateSchema = z.object({
    status: z.enum([
        "APPLIED", "UNDER_REVIEW", "SHORTLISTED", "REJECTED",
        "INTERVIEW_SCHEDULED", "INTERVIEW_COMPLETED",
        "SELECTED", "WAITLISTED", "FURTHER_ROUND"
    ])
});
export const PUT = async (req, res) => {
    const params = req.params;
    try {
        const session = await getSession(req);
        if (!session || (session.role !== "ADMIN" && session.role !== "RECRUITER")) {
            return res.status(403).json({ error: "Forbidden" });
        }
        const resolvedParams = req.params;
        const id = parseInt(resolvedParams.id, 10);
        const body = req.body;
        const parsed = updateSchema.safeParse(body);
        if (!parsed.success) {
            return res.status(400).json({ error: "Invalid status value" });
        }
        const { status } = parsed.data;
        const existingApplication = await prisma.application.findUnique({
            where: { id },
            include: { candidate: true }
        });
        if (!existingApplication) {
            return res.status(404).json({ error: "Application not found" });
        }
        // Recruiter Department Authorization
        if (session.role === "RECRUITER") {
            const isAssigned = session.departments?.includes(existingApplication.candidate.department);
            if (!isAssigned) {
                return res.status(403).json({ error: "Forbidden: Candidate belongs to unassigned department" });
            }
        }
        // Valid Status Lifecycle checks
        const currentStatus = existingApplication.status;
        const validTransitions = {
            "APPLIED": ["UNDER_REVIEW", "REJECTED"],
            "UNDER_REVIEW": ["SHORTLISTED", "REJECTED"],
            "SHORTLISTED": ["INTERVIEW_SCHEDULED", "REJECTED"],
            "INTERVIEW_SCHEDULED": ["INTERVIEW_COMPLETED", "REJECTED"],
            "INTERVIEW_COMPLETED": ["SELECTED", "REJECTED", "WAITLISTED", "FURTHER_ROUND"],
            "WAITLISTED": ["SELECTED", "REJECTED"],
            "FURTHER_ROUND": ["INTERVIEW_SCHEDULED", "REJECTED"]
        };
        const allowedNext = validTransitions[currentStatus] || [];
        if (!allowedNext.includes(status)) {
            return res.status(400).json({ error: `Invalid transition from ${currentStatus} to ${status}` });
        }
        // Req 7: Block generic PUT from manually setting INTERVIEW_COMPLETED
        if (status === "INTERVIEW_COMPLETED") {
            return res.status(400).json({ error: "Interview completion is controlled by the interview feedback workflow" });
        }
        // Final decisions require full feedback verification
        const finalDecisions = ["SELECTED", "WAITLISTED"];
        const isFinalDecision = finalDecisions.includes(status) || (status === "REJECTED" && currentStatus === "INTERVIEW_COMPLETED");
        // FURTHER_ROUND also requires feedback verification but is NOT a final decision
        const requiresFeedbackVerification = isFinalDecision || status === "FURTHER_ROUND";
        if (requiresFeedbackVerification) {
            // Must verify actual workflow, not just application status
            const latestInterview = await prisma.interview.findFirst({
                where: { application_id: id },
                orderBy: { round: 'desc' },
                include: { assigned_members: true, feedback: true }
            });
            if (!latestInterview) {
                return res.status(400).json({ error: "Cannot transition status: No interview found for this application." });
            }
            if (latestInterview.status !== "FEEDBACK_SUBMITTED") {
                return res.status(400).json({ error: "Cannot transition status: Interview is not fully completed or feedback is missing." });
            }
            const requiredMemberIds = latestInterview.assigned_members.map((m) => m.id).sort();
            const submittedFeedbackIds = latestInterview.feedback.map((f) => f.panel_member_id).sort();
            const allSubmitted = requiredMemberIds.length > 0 &&
                requiredMemberIds.length === submittedFeedbackIds.length &&
                requiredMemberIds.every((mid, index) => mid === submittedFeedbackIds[index]);
            if (!allSubmitted) {
                return res.status(400).json({ error: "Cannot transition status: Not all exact panel members have submitted feedback." });
            }
        }
        const updateData = { status };
        // Only true final decisions set decided_by/decided_at. FURTHER_ROUND is NOT a final decision.
        const isTrueFinal = ["SELECTED", "REJECTED", "WAITLISTED"].includes(status);
        if (isTrueFinal) {
            updateData.decided_by = session.id;
            updateData.decided_at = new Date();
            if (body.reason) {
                updateData.decision_reason = body.reason;
            }
        }
        const application = await prisma.application.update({
            where: { id },
            data: updateData,
            include: { candidate: true }
        });
        // Log the audit event
        await logAudit(session.id, `UPDATED_APPLICATION_STATUS_TO_${status}`, "Application", id);
        await createNotification(session.id, `Application Status Updated`, `${application.candidate.name}'s application was marked as ${status}.`);
        return res.status(200).json({ application });
    }
    catch (error) {
        console.error("Update application error:", error);
        return res.status(500).json({ error: "Internal server error" });
    }
};

import prisma from "../../lib/db";
import { getSession } from "../../lib/auth";
export const GET = async (req, res) => {
    const params = req.params;
    try {
        const session = await getSession(req);
        if (!session)
            return res.status(401).json({ error: "Unauthorized" });
        const resolvedParams = req.params;
        const id = parseInt(resolvedParams.id, 10);
        let includeClause = {
            applications: true,
            interviews: {
                include: { panel: true, feedback: true }
            }
        };
        if (session.role === "PANEL_MEMBER") {
            includeClause = {
                applications: {
                    where: {
                        interviews: {
                            some: {
                                assigned_members: { some: { user_id: session.id } }
                            }
                        }
                    }
                },
                interviews: {
                    where: {
                        assigned_members: { some: { user_id: session.id } }
                    },
                    include: { feedback: true } // Removed panel include to restrict unnecessary data
                }
            };
        }
        const candidate = await prisma.candidate.findUnique({
            where: { id },
            include: includeClause
        });
        if (!candidate)
            return res.status(404).json({ error: "Not found" });
        // Access control: Recruiter can only view their own department
        if (session.role === "RECRUITER" && !session.departments.includes(candidate.department)) {
            return res.status(403).json({ error: "Forbidden" });
        }
        // Access control: Panel Member
        if (session.role === "PANEL_MEMBER" && candidate.interviews.length === 0) {
            return res.status(403).json({ error: "Forbidden" });
        }
        return res.status(200).json({ candidate });
    }
    catch (error) {
        console.error("Fetch candidate error:", error);
        return res.status(500).json({ error: "Internal server error" });
    }
};

import prisma from "../../lib/db";
import { getSession } from "../../lib/auth";
import { logAudit } from "../../lib/audit";
export const GET = async (req, res) => {
    const params = req.params;
    try {
        const resolvedParams = req.params;
        const id = parseInt(resolvedParams.id, 10);
        const form = await prisma.form.findUnique({
