import { toISTDateString } from "../lib/timezone"

export const GET = async (req: Request, res: Response) => {
  try {
    const session = await getSession(req)
    if (!session || session.role !== "ADMIN") {
      return res.status(403).json({ error: "Forbidden" })
    }

    // Basic metrics aggregation for dashboard
    const totalApplications = await prisma.application.count()
    const totalCandidates = await prisma.candidate.count()
    const totalInterviews = await prisma.interview.count()
    const totalRecruiters = await prisma.user.count({ where: { role: 'RECRUITER' } })
    const totalPanels = await prisma.panel.count()

    const shortlisted = await prisma.application.count({ where: { status: 'SHORTLISTED' } })
    const scheduledInterviews = await prisma.application.count({ where: { status: 'INTERVIEW_SCHEDULED' } })
    const completedInterviews = await prisma.application.count({ where: { status: 'INTERVIEW_COMPLETED' } })
    const selectedCandidates = await prisma.application.count({ where: { status: 'SELECTED' } })
    const rejectedCandidates = await prisma.application.count({ where: { status: 'REJECTED' } })
    
    // In our system, feedback pending can be determined by interviews without sufficient feedback or specific application status.
    // For simplicity, we just count applications that are waitlisted or require review
    const pendingFeedback = await prisma.interview.count({ where: { status: 'FEEDBACK_PENDING' } })

    // Analytics: Applications by status
    const applicationsByStatusRaw = await prisma.application.groupBy({
      by: ['status'],
      _count: { status: true }
    })
    const applicationsByStatus = applicationsByStatusRaw.reduce((acc: any, curr: any) => {
      acc[curr.status] = curr._count.status
      return acc
    }, {})

    // Analytics: Department Distribution (by applications, not candidates)
    const departmentsWithApps = await prisma.candidate.findMany({
      select: {
        department: true,
        _count: { select: { applications: true } }
      }
    })
    
    const deptMap: Record<string, number> = {}
    for (const d of departmentsWithApps) {
      deptMap[d.department] = (deptMap[d.department] || 0) + d._count.applications
    }
    
    const applicationsByDepartment = Object.keys(deptMap).map(dept => ({
      department: dept,
      count: deptMap[dept]
    }))

    // Analytics: Selected vs Rejected
    const selectedVsRejected = {
      SELECTED: selectedCandidates,
      REJECTED: rejectedCandidates
    }

    // Analytics: Interviews by day
    // We will fetch all interviews and group them in memory since Prisma doesn't natively group by Date cast easily in raw JS
    const allInterviews = await prisma.interview.findMany({
      select: { start_time: true }
    })
    
    const interviewsByDayRaw: Record<string, number> = {}
    allInterviews.forEach((inv: any) => {
      // Convert to Asia/Kolkata date for grouping (Req 25)
      const istDate = toISTDateString(inv.start_time)
      interviewsByDayRaw[istDate] = (interviewsByDayRaw[istDate] || 0) + 1
    })

    const interviewsByDay = Object.keys(interviewsByDayRaw)
      .sort()
      .map(date => ({ date, count: interviewsByDayRaw[date] }))

    // Recent activity from audit logs
    const recentActivity = await prisma.auditLog.findMany({
      include: {
        user: { select: { name: true, email: true, role: true } }
      },
      orderBy: { timestamp: 'desc' },
      take: 10
    })

    return res.status(200).json({
      metrics: {
        totalApplications,
        totalCandidates,
        totalInterviews,
        totalRecruiters,
        totalPanels,
        shortlisted,
        scheduledInterviews,
        completedInterviews,
        selectedCandidates,
        rejectedCandidates,
        pendingFeedback
      },
      applicationsByStatus,
      applicationsByDepartment,
      selectedVsRejected,
      interviewsByDay,
      recentActivity
    })
  } catch (error) {
    console.error("Fetch analytics error:", error)
    return res.status(500).json({ error: "Internal server error" })
  }
}

import { Request, Response } from "express";
import prisma from "../lib/db"
import { getSession } from "../lib/auth"
import { createNotification } from "../lib/notify"
import { logAudit } from "../lib/audit"
import { z } from "zod"
import { getISTDateBounds } from "../lib/timezone"

const applicationSchema = z.object({
  name: z.string().min(2),
  email: z.string().email(),
  phone: z.string().min(10),
  department: z.string().min(2),
  registration_number: z.string().min(4),
  resume_url: z.string().url().refine(val => val.startsWith('https://'), { message: "resume_url must use HTTPS protocol" }).optional().or(z.literal('')),
  form_id: z.number().int().positive(),
  answers: z.record(z.string(), z.union([z.string(), z.array(z.string())])).optional()
})

export const POST = async (req: Request, res: Response) => {
  try {
    const body = req.body
    const parsed = applicationSchema.safeParse(body)
    
    if (!parsed.success) {
      return res.status(400).json({ error: "Invalid form data", details: parsed.error.format() })
    }

    const data = parsed.data

    // Check if form is published and load questions
    const form = await prisma.form.findUnique({ 
      where: { id: data.form_id },
      include: { questions: true }
    })
    
    if (!form || form.status !== "PUBLISHED") {
      return res.status(400).json({ error: "Form is not active or does not exist." })
    }

    // Dynamic Answer Validation
    const submittedAnswers: Record<string, any> = data.answers || {}
    
    const validQuestionIds = new Set(form.questions.map((q: any) => q.id.toString()))
    for (const key in submittedAnswers) {
      if (!validQuestionIds.has(key)) {
        return res.status(400).json({ error: `Unknown question ID submitted: ${key}` })
      }
    }

    for (const q of form.questions) {
      const answer = submittedAnswers[q.id.toString()]
      
      // 1. Required check
      if (q.required && (answer === undefined || answer === null || answer === "" || (Array.isArray(answer) && answer.length === 0))) {
        return res.status(400).json({ error: `Question '${q.question}' is required.` })
      }

      if (answer !== undefined && answer !== null && answer !== "") {
        // 2. Options validation for RADIO and DROPDOWN
        if ((q.type === 'RADIO' || q.type === 'DROPDOWN') && q.options.length > 0) {
          if (!q.options.includes(String(answer))) {
            return res.status(400).json({ error: `Invalid option selected for '${q.question}'.` })
          }
        }
        
        // 3. Options validation for CHECKBOX (answers could be array or comma-separated string)
        if (q.type === 'CHECKBOX' && q.options.length > 0) {
          let selected: string[] = []
          if (Array.isArray(answer)) selected = answer
          else if (typeof answer === 'string') selected = answer.split(',').map(s => s.trim())
          else selected = [String(answer)]
          
          for (const s of selected) {
            if (!q.options.includes(s)) {
              return res.status(400).json({ error: `Invalid option '${s}' selected for '${q.question}'.` })
            }
          }
        }
      }
    }

    // 1. Check duplicate candidate globally or just use unique constraint
    let candidate = await prisma.candidate.findFirst({
      where: {
        OR: [
          { email: data.email },
          { registration_number: data.registration_number }
        ]
      }
    })

    if (candidate) {
      if (candidate.email !== data.email || candidate.registration_number !== data.registration_number) {
        return res.status(400).json({ error: "Identity mismatch. Please use the exact email and registration number you previously used." })
      }
    }

    if (!candidate) {
      candidate = await prisma.candidate.create({
        data: {
          name: data.name,
          email: data.email,
          phone: data.phone,
          department: data.department,
          registration_number: data.registration_number,
          resume_url: data.resume_url || null,
        },
      })
    }

    // 2. Create Application
    const application = await prisma.application.create({
      data: {
        candidate_id: candidate.id,
        form_id: data.form_id,
        status: "APPLIED",
        answers: data.answers || {},
      },
    })

    // Find recruiters in this department to notify them
    const recruiters = await prisma.user.findMany({
      where: {
        role: "RECRUITER",
        departments: {
          has: data.department,
        },
      },
    })

    for (const recruiter of recruiters) {
      await createNotification(
        recruiter.id,
        "New Application Submitted",
        `${candidate.name} applied for the ${candidate.department} department.`
      )
    }

    // System audit log (nullable user_id for system actions)
    await logAudit(undefined, "APPLICATION_SUBMITTED", "Application", application.id)

    return res.status(201).json(
      { message: "Application submitted successfully", applicationId: application.id })
  } catch (error: any) {
    console.error("Application submission error:", error)
    if (error.code === 'P2002') {
      return res.status(409).json({ error: "An application for this form already exists." })
    }
    return res.status(500).json(
      { error: "Internal server error" })
  }
}

export const GET = async (req: Request, res: Response) => {
  try {
        const session = await getSession(req)
    if (!session) {
      return res.status(401).json({ error: "Unauthorized" })
    }

    const searchParams = new URLSearchParams(req.query as any)
    const page = Math.max(1, parseInt(searchParams.get("page") || "1") || 1)
    const limit = Math.min(100, Math.max(1, parseInt(searchParams.get("limit") || "10") || 10))
    const search = searchParams.get("search") || ""
    const status = searchParams.get("status") || ""
    const department = searchParams.get("department") || ""
    const date = searchParams.get("date") || ""

    const skip = (page - 1) * limit

    const where: any = {}

        // Build candidate filter object
    const candidateFilter: any = {}

    if (department) {
      if (session.role === "RECRUITER") {
        if (session.departments.includes(department)) {
          candidateFilter.department = department
        } else {
          return res.status(403).json({ error: "Forbidden: Department not assigned" })
        }
      } else if (session.role === "ADMIN") {
        candidateFilter.department = department
      }
    } else if (session.role === "RECRUITER") {
      candidateFilter.department = { in: session.departments }
    } else if (session.role === "PANEL_MEMBER") {
      where.interviews = {
        some: {
          assigned_members: {
            some: { user_id: session.id }
          }
        }
      }
    }

    // Search filter
    if (search) {
      candidateFilter.name = { contains: search, mode: "insensitive" }
    }

    // Only set where.candidate if we have filters
    if (Object.keys(candidateFilter).length > 0) {
      where.candidate = candidateFilter
    }

    if (status) {
      where.status = status
    }

    if (date) {
      // Use centralized IST boundaries (Req 17)
      const { startOfDay, endOfDay } = getISTDateBounds(date)
      where.submitted_at = {
        gte: startOfDay,
        lte: endOfDay
      }
    }

    const [items, total] = await Promise.all([
      prisma.application.findMany({
        where,
        include: {
          candidate: true,
          form: true,
        },
        skip,
        take: limit,
        orderBy: { submitted_at: "desc" },
      }),
      prisma.application.count({ where })
    ])

    return res.status(200).json({
      items,
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit)
    })
  } catch (error) {
    console.error("Fetch applications error:", error)
    return res.status(500).json({ error: "Internal server error" })
  }
}

