export const DELETE = async (req: Request, res: Response) => {
  try {
    const session = await getSession(req)
    if (!session || session.role !== "ADMIN") {
      return res.status(403).json({ error: "Forbidden" })
    }

    const { id } = req.body

    if (!id) {
      return res.status(400).json({ error: "Missing panel ID" })
    }

    const panelRelations = await prisma.panel.findUnique({
      where: { id },
      include: { interviews: { take: 1 } }
    })

    if (!panelRelations) {
      return res.status(404).json({ error: "Panel not found" })
    }

    if (panelRelations.interviews.length > 0) {
      // Prevent deletion, deactivate instead
      await prisma.panel.update({
        where: { id },
        data: { status: "INACTIVE" }
      })
      await logAudit(session.id, "DEACTIVATED_PANEL", "Panel", id)
      return res.status(200).json({ success: true, message: "Panel deactivated because it has historical interviews." })
    }

    // Must delete panel members first due to foreign key
    await prisma.panelMember.deleteMany({
      where: { panel_id: id }
    })

    await prisma.panel.delete({
      where: { id }
    })

    await logAudit(session.id, "DELETED_PANEL", "Panel", id)

    return res.status(200).json({ success: true })
  } catch (error) {
    console.error("Delete panel error:", error)
    return res.status(500).json({ error: "Internal server error" })
  }
}

import { Request, Response } from "express";
import prisma from "../../lib/db"
import { getSession } from "../../lib/auth"
import { getISTDateBounds } from "../../lib/timezone"

export const GET = async (req: Request, res: Response) => {
  try {
    const session = await getSession(req)
    if (!session || session.role !== "PANEL_MEMBER") {
      return res.status(403).json({ error: "Forbidden" })
    }

    const { startOfDay: startOfToday, endOfDay: endOfToday, endOfWeek } = getISTDateBounds()

    // 1. Interviews Today (IST)
    const todayInterviewsCount = await prisma.interview.count({
      where: {
        date: {
          gte: startOfToday,
          lte: endOfToday
        },
        status: { not: "CANCELLED" },
        assigned_members: {
          some: { user_id: session.id }
        }
      }
    })

    // 2. Upcoming (Week, IST)
    const upcomingInterviewsCount = await prisma.interview.count({
      where: {
        date: {
          gt: endOfToday,
          lte: endOfWeek
        },
        status: { not: "CANCELLED" },
        assigned_members: {
          some: { user_id: session.id }
        }
      }
    })

    // 3. Pending Feedback
    // Only COMPLETED and FEEDBACK_PENDING interviews count.
    // SCHEDULED interviews are NOT eligible for feedback (Req 12).
    // Note: We DO NOT filter by `active: true` here because of Req 4: 
    // Historical pending feedback must still be accessible if they were assigned to it.
    const panelMemberRows = await prisma.panelMember.findMany({
      where: { user_id: session.id }
    })
    const panelMemberIds = panelMemberRows.map((pm: any) => pm.id)

    const pendingFeedbackCount = await prisma.interview.count({
      where: {
        status: { in: ["COMPLETED", "FEEDBACK_PENDING"] },
        assigned_members: {
          some: { user_id: session.id }
        },
        NOT: {
          feedback: {
            some: {
              panel_member_id: { in: panelMemberIds }
            }
          }
        }
      }
    })

    // 4. Today's Schedule (IST)
    const todaySchedule = await prisma.interview.findMany({
      where: {
        date: {
          gte: startOfToday,
          lte: endOfToday
        },
        status: { not: "CANCELLED" },
        assigned_members: {
          some: { user_id: session.id }
        }
      },
      include: {
        candidate: {
          select: { // Req 3: Data minimization
            id: true,
            name: true,
            email: true,
            department: true,
            registration_number: true
          }
        }
      },
      orderBy: {
        start_time: 'asc'
      }
    })

    return res.status(200).json({
      stats: {
        todayInterviewsCount,
        upcomingInterviewsCount,
        pendingFeedbackCount
      },
      todaySchedule
    })
  } catch (error) {
    console.error("Panel dashboard error:", error)
    return res.status(500).json({ error: "Internal server error" })
  }
}

