                        {formatTime(interview.start_time)} - {formatTime(interview.end_time)}
                      </p>
                    </td>
                    <td className="p-4">
                      <p className="text-[#f4ede4] font-medium">{interview.candidate?.name}</p>
                      <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">{interview.candidate?.department}</p>
                    </td>
                    <td className="p-4">
                      <StatusPill status={interview.status === 'FEEDBACK_SUBMITTED' ? 'completed' : 'pending'}>
                        {interview.status}
                      </StatusPill>
                    </td>
                    <td className="p-4 flex gap-3">
                      {interview.status !== "FEEDBACK_SUBMITTED" ? (
                        <Link href={`/panel/feedback/${interview.id}`}>
                          <Button variant="cta" className="py-2 px-4 text-xs">EVALUATE</Button>
                        </Link>
                      ) : (
                        <Link href={`/panel/interview/${interview.id}`}>
                          <Button variant="ghost" className="py-2 px-4 text-xs text-[#2e7d32]">REVIEW SUBMISSION</Button>
                        </Link>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  )
}

