"use client"
import { fetchApi } from "@/api-client"

import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"

export default function RecruiterApplicationsPage() {
  const [applications, setApplications] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  
  // Filters & Pagination
  const [search, setSearch] = useState("")
  const [status, setStatus] = useState("")
  const [department, setDepartment] = useState("")
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  
  const [debouncedSearch, setDebouncedSearch] = useState("")

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 500)
    return () => clearTimeout(timer)
  }, [search])

  useEffect(() => {
    fetchApplications()
  }, [debouncedSearch, status, department, page])

  const fetchApplications = async () => {
    setLoading(true)
    try {
      const query = new URLSearchParams({
        page: page.toString(),
        limit: "10",
        search: debouncedSearch,
        status,
        department
      })
      const res = await fetchApi(`/api/applications?${query.toString()}`)
      const data = await res.json()
      setApplications(data.items || [])
      setTotalPages(data.totalPages || 1)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("en-US", { timeZone: "Asia/Kolkata", 
      month: "short", day: "numeric", year: "numeric"
    })
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out] pb-10">
      <header className="flex flex-col gap-2">
        <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
          <DiamondIcon />
          <span>Department View</span>
        </div>
        <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
          Applications Master
        </h1>
      </header>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-4 bg-[#120202] p-4 rounded-xl border border-[#2a0d0d]">
        <div className="flex-1 relative">
          <input 
            type="text" 
            placeholder="Search candidate name..." 
            className="w-full bg-[#1a0606] border border-[#2a0d0d] rounded-lg px-4 py-2.5 text-[#f4ede4] font-mono text-[12px] focus:outline-none focus:border-[#ac120c]"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
          />
        </div>
        <div className="flex flex-col sm:flex-row gap-4">
          <select 
            className="bg-[#1a0606] border border-[#2a0d0d] rounded-lg px-4 py-2.5 text-[#f4ede4] font-mono text-[12px] focus:outline-none focus:border-[#ac120c]"
            value={status}
            onChange={(e) => { setStatus(e.target.value); setPage(1); }}
          >
            <option value="">All Statuses</option>
            <option value="APPLIED">Applied</option>
            <option value="UNDER_REVIEW">Under Review</option>
            <option value="SHORTLISTED">Shortlisted</option>
            <option value="INTERVIEW_SCHEDULED">Interview Scheduled</option>
            <option value="INTERVIEW_COMPLETED">Interview Completed</option>
            <option value="WAITLISTED">Waitlisted</option>
            <option value="SELECTED">Selected</option>
            <option value="REJECTED">Rejected</option>
          </select>

          <select 
            className="bg-[#1a0606] border border-[#2a0d0d] rounded-lg px-4 py-2.5 text-[#f4ede4] font-mono text-[12px] focus:outline-none focus:border-[#ac120c]"
            value={department}
            onChange={(e) => { setDepartment(e.target.value); setPage(1); }}
          >
            <option value="">All Assigned Depts</option>
            <option value="Web Development">Web Development</option>
            <option value="AI/ML">AI/ML</option>
            <option value="App Development">App Development</option>
            <option value="Design">Design</option>
            <option value="Events">Events</option>
            <option value="Operations">Operations</option>
            <option value="Competitive Programming">Competitive Programming</option>
            <option value="Cybersecurity">Cybersecurity</option>
          </select>
        </div>
      </div>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[800px]">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">CANDIDATE NAME</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">EMAIL</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">DEPT</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">APP DATE</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">APP STATUS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em] text-right">ACTIONS</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-[#bfa8a2] font-mono">LOADING DATA...</td></tr>
              ) : applications.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-[#bfa8a2] font-mono">NO APPLICATIONS FOUND.</td></tr>
              ) : (
                applications.map((app) => {
                  const c = app.candidate
                  return (
                    <tr key={app.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                      <td className="p-4 text-[#f4ede4] font-medium">{c?.name || "Unknown"}</td>
                      <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">{c?.email || "-"}</td>
                      <td className="p-4 text-[#bfa8a2]">{c?.department || "-"}</td>
                      <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">
                        {app.submitted_at ? formatDate(app.submitted_at) : "-"}
                      </td>
                      <td className="p-4">
                        <StatusPill status={app.status.toLowerCase().includes('reject') ? 'rejected' : 'pending'}>
                          {app.status || "APPLIED"}
                        </StatusPill>
                      </td>
                      <td className="p-4 text-right">
                        <a href={`/recruiter/candidates/${c?.id}`} className="text-[#d07d22] font-mono text-[10px] uppercase hover:underline">
                          VIEW PROFILE
                        </a>
                      </td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>
      </Card>
      
      {/* Pagination */}
      {!loading && totalPages > 1 && (
        <div className="flex justify-between items-center bg-[#120202] p-4 rounded-xl border border-[#2a0d0d]">
          <Button 
            variant="ghost" 
            onClick={() => setPage(p => Math.max(1, p - 1))}
            disabled={page === 1}
          >
            PREV
          </Button>
          <span className="font-mono text-[#bfa8a2] text-[12px]">
            PAGE {page} OF {totalPages}
          </span>
          <Button 
            variant="ghost" 
            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
          >
            NEXT
          </Button>
        </div>
      )}
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { useParams, useRouter } from "next/navigation"
import { Card } from "@/components/ui/Card"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"

export default function RecruiterCandidateProfile() {
  const { id } = useParams()
  const router = useRouter()
  const [candidate, setCandidate] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState(false)
  const [error, setError] = useState("")

  useEffect(() => {
    fetchCandidate()
  }, [id])

  const fetchCandidate = async () => {
    try {
      const res = await fetchApi(`/api/candidates/${id}`)
      if (!res.ok) throw new Error("Failed to fetch")
      const data = await res.json()
      setCandidate(data.candidate)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const updateApplicationStatus = async (appId: number, status: string) => {
    if (!confirm(`Are you sure you want to mark this application as ${status}?`)) return;
    
    setActionLoading(true)
    setError("")
    try {
      const res = await fetchApi(`/api/applications/${appId}`, {  
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status })
      })
      if (!res.ok) {
        const d = await res.json()
        throw new Error(d.error || "Failed to update status")
      }
      fetchCandidate()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setActionLoading(false)
    }
  }

  if (loading) return <div className="p-8 text-center text-[#bfa8a2] font-mono">LOADING PROFILE...</div>
  if (!candidate) return <div className="p-8 text-center text-[#bfa8a2] font-mono">CANDIDATE NOT FOUND.</div>

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <div className="flex justify-between items-center">
        <h1 className="font-display font-bold text-[32px] sm:text-[40px] text-[#f4ede4]">
          {candidate.name}
        </h1>
        <Button variant="ghost" onClick={() => router.back()}>BACK</Button>
      </div>

      {error && (
        <div className="bg-[#ac120c]/10 border border-[#ac120c]/50 text-[#ac120c] p-4 rounded-lg text-sm font-medium">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card className="p-6">
          <h2 className="text-[#d07d22] font-mono text-[14px] uppercase mb-4">Contact Information</h2>
          <div className="flex flex-col gap-3 text-[#f4ede4]">
            <p><span className="text-[#bfa8a2] font-mono mr-2">EMAIL:</span> {candidate.email}</p>
            <p><span className="text-[#bfa8a2] font-mono mr-2">PHONE:</span> {candidate.phone}</p>
            <p><span className="text-[#bfa8a2] font-mono mr-2">REG NO:</span> {candidate.registration_number}</p>
            <p><span className="text-[#bfa8a2] font-mono mr-2">DEPT:</span> {candidate.department}</p>
            {candidate.resume_url && (
              <p>
                <span className="text-[#bfa8a2] font-mono mr-2">RESUME:</span>
                <a href={candidate.resume_url} target="_blank" rel="noreferrer" className="text-[#d07d22] underline">View Resume</a>
              </p>
            )}
          </div>
        </Card>

        <Card className="p-6">
          <h2 className="text-[#d07d22] font-mono text-[14px] uppercase mb-4">Applications</h2>
          <div className="flex flex-col gap-4">
            {candidate.applications?.map((app: any) => (
              <div key={app.id} className="bg-[#1a0606] p-4 rounded border border-[#2a0d0d]">
                <div className="flex justify-between items-center mb-2">
                  <span className="font-mono text-[#bfa8a2] text-[12px]">Application #{app.id}</span>
                  <StatusPill status={app.status.toLowerCase().includes('reject') ? 'rejected' : 'pending'}>
                    {app.status}
                  </StatusPill>
                </div>
                <div className="mt-4 flex flex-col gap-3">
                  {Object.entries(app.answers || {}).length > 0 ? (
                    Object.entries(app.answers).map(([questionId, answer]: [string, any]) => (
                      <div key={questionId} className="bg-[#2a0d0d]/30 p-3 rounded">
                        <div className="font-mono text-[10px] text-[#bfa8a2] mb-1">QUESTION ID: {questionId}</div>
                        <div className="font-body text-[14px] text-[#f4ede4] whitespace-pre-wrap">{String(answer)}</div>
                      </div>
                    ))
                  ) : (
                    <p className="text-[12px] text-[#bfa8a2]">No answers provided.</p>
                  )}
                </div>
                <div className="flex gap-2 flex-wrap border-t border-[#2a0d0d] pt-3 mt-4">
                  {(app.status === "APPLIED") && (
                    <>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "UNDER_REVIEW")} disabled={actionLoading} className="text-[#3498db] border border-[#3498db] hover:bg-[#3498db] hover:text-[#0a0202]">Mark Under Review</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                  {(app.status === "UNDER_REVIEW") && (
                    <>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "SHORTLISTED")} disabled={actionLoading} className="text-[#d07d22] border border-[#d07d22] hover:bg-[#d07d22] hover:text-[#0a0202]">Shortlist</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                  
                  {(app.status === "SHORTLISTED" || app.status === "FURTHER_ROUND") && (
                    <>
                      <Button variant="primary" onClick={() => router.push(`/recruiter/meetings?scheduleFor=${candidate.id}`)} disabled={actionLoading}>Schedule Interview</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                  
                  {(app.status === "INTERVIEW_COMPLETED" || app.status === "WAITLISTED") && (
                    <>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "SELECTED")} disabled={actionLoading} className="text-[#2ecc71] border border-[#2ecc71] hover:bg-[#2ecc71] hover:text-[#0a0202]">Select</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "WAITLISTED")} disabled={actionLoading} className="text-[#f1c40f] border border-[#f1c40f] hover:bg-[#f1c40f] hover:text-[#0a0202]">Waitlist</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "FURTHER_ROUND")} disabled={actionLoading} className="text-[#3498db] border border-[#3498db] hover:bg-[#3498db] hover:text-[#0a0202]">Further Round</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>

      <Card className="p-6">
        <h2 className="text-[#d07d22] font-mono text-[14px] uppercase mb-4">Interview History</h2>
        {candidate.interviews?.length === 0 ? (
          <p className="text-[#bfa8a2] font-mono">No interviews scheduled.</p>
        ) : (
          <div className="flex flex-col gap-6">
            {candidate.interviews?.map((interview: any, i: number) => (
              <div key={interview.id} className="bg-[#1a0606] p-4 rounded border border-[#2a0d0d] flex flex-col gap-4">
                <div className="flex justify-between border-b border-[#2a0d0d] pb-2">
                  <h3 className="text-[#f4ede4] font-medium">Round {i + 1} - {new Date(interview.date).toLocaleDateString('en-US', { timeZone: 'Asia/Kolkata' })}</h3>
                  <StatusPill status={interview.status === 'COMPLETED' ? 'selected' : 'pending'}>{interview.status}</StatusPill>
                </div>
                
                <div className="flex flex-col gap-2">
                  <p className="text-[#bfa8a2] text-sm">Time: {new Date(interview.start_time).toLocaleTimeString('en-US', { timeZone: 'Asia/Kolkata' })} - {new Date(interview.end_time).toLocaleTimeString('en-US', { timeZone: 'Asia/Kolkata' })}</p>
                  {interview.meeting_link && (
                    <a href={interview.meeting_link} target="_blank" rel="noreferrer" className="text-[#d07d22] text-sm underline">Join Meeting</a>
                  )}
                </div>

                {interview.feedback && interview.feedback.length > 0 && (
                  <div className="mt-2">
                    <h4 className="text-[#d07d22] font-mono text-[12px] uppercase mb-2">Feedback</h4>
                    {interview.feedback.map((fb: any) => (
                      <div key={fb.id} className="bg-[#2a0d0d]/30 p-3 rounded mb-2 text-sm text-[#f4ede4]">
                        <p><span className="text-[#bfa8a2]">Score:</span> {fb.overall_score} / 25</p>
                        <p><span className="text-[#bfa8a2]">Recommendation:</span> {fb.recommendation}</p>
                        <p className="mt-1 text-[#bfa8a2] italic">"{fb.comments}"</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import Link from "next/link"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Input } from "@/components/ui/Input"
import { Button } from "@/components/ui/Button"

export default function CandidatesPage() {
  const [candidates, setCandidates] = useState<any[]>([])
  const [search, setSearch] = useState("")
  const [statusFilter, setStatusFilter] = useState("ALL")
  const [departmentFilter, setDepartmentFilter] = useState("ALL")
  const [dateFilter, setDateFilter] = useState("")
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetchCandidates()
  }, [search, statusFilter, departmentFilter, dateFilter])

  const fetchCandidates = async () => {
    setLoading(true)
    try {
      // In a real app, pass search and statusFilter to API as query params
      const res = await fetchApi(`/api/candidates`)
      const data = await res.json()
      
      // Client side filtering for completeness
      let filtered = data.candidates || []
      
      if (search) {
        filtered = filtered.filter((c: any) => 
          c.name.toLowerCase().includes(search.toLowerCase()) || 
          c.email.toLowerCase().includes(search.toLowerCase()) ||
          c.registration_number?.toLowerCase().includes(search.toLowerCase())
        )
      }
      
      if (statusFilter !== "ALL") {
        filtered = filtered.filter((c: any) => {
          const latestApp = c.applications?.[c.applications.length - 1]
          const appStatus = latestApp?.status || "APPLIED"
          return appStatus === statusFilter
        })
      }
      
      if (departmentFilter !== "ALL") {
        filtered = filtered.filter((c: any) => c.department === departmentFilter)
      }

      if (dateFilter) {
        filtered = filtered.filter((c: any) => {
          const latestApp = c.applications?.[c.applications.length - 1]
          const appDate = latestApp?.submitted_at
          if (!appDate) return false
          return new Date(appDate).toISOString().split('T')[0] === dateFilter
        })
      }
      
      setCandidates(filtered)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>Candidate Management</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            Candidates Pool
          </h1>
        </div>
      </header>

      {/* Filters */}
      <Card className="flex flex-col sm:flex-row gap-4 p-4 items-center">
        <div className="w-full sm:w-2/5">
          <Input 
            placeholder="Search by name, email, or registration..." 
            value={search}
            onChange={(e: any) => setSearch(e.target.value)}
          />
        </div>
        <div className="w-full sm:w-1/5">
          <select 
            className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono text-[12px] focus:outline-none focus:border-[#d07d22]"
            value={departmentFilter}
            onChange={(e) => setDepartmentFilter(e.target.value)}
          >
            <option value="ALL">All Depts</option>
            <option value="CSE">CSE</option>
            <option value="ECE">ECE</option>
            <option value="EEE">EEE</option>
            <option value="MECH">MECH</option>
          </select>
        </div>
        <div className="w-full sm:w-1/5">
          <select 
            className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono text-[12px] focus:outline-none focus:border-[#d07d22]"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            <option value="ALL">All Statuses</option>
            <option value="APPLIED">Applied</option>
            <option value="SHORTLISTED">Shortlisted</option>
            <option value="REJECTED">Rejected</option>
          </select>
        </div>
        <div className="w-full sm:w-1/5">
          <Input 
            type="date"
            value={dateFilter}
            onChange={(e: any) => setDateFilter(e.target.value)}
          />
        </div>
        <Button variant="ghost" className="w-full sm:w-auto h-[46px]" onClick={fetchCandidates}>
          REFRESH
        </Button>
      </Card>

      {/* Candidates Table */}
      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">REG NO</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">CANDIDATE</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">DEPARTMENT</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">STATUS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">ACTIONS</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {loading ? (
                <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">LOADING DATA...</td></tr>
              ) : candidates.length === 0 ? (
                <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">NO CANDIDATES FOUND.</td></tr>
              ) : (
                candidates.map((candidate) => {
                  const latestApp = candidate.applications?.[candidate.applications.length - 1]
                  const appStatus = latestApp?.status || "APPLIED"
                  return (
                    <tr key={candidate.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                      <td className="p-4 text-[#d07d22] font-mono text-[13px] font-bold">{candidate.registration_number}</td>
                      <td className="p-4">
                        <p className="text-[#f4ede4] font-medium">{candidate.name}</p>
                        <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">{candidate.email}</p>
                      </td>
                      <td className="p-4 text-[#bfa8a2]">{candidate.department}</td>
                      <td className="p-4">
                        <StatusPill status={appStatus.toLowerCase().includes('reject') ? 'rejected' : 'pending'}>
                          {appStatus}
                        </StatusPill>
                      </td>
                      <td className="p-4">
                        <Link href={`/recruiter/candidates/${candidate.id}`}>
                          <Button variant="ghost" className="py-2 px-4 text-xs">VIEW PROFILE</Button>
                        </Link>
                      </td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"

import React, { useState, useEffect } from "react"
import Link from "next/link"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Input } from "@/components/ui/Input"
import { Button } from "@/components/ui/Button"
import { Modal } from "@/components/ui/Modal"

export default function RecruiterMeetingsPage() {
  const [interviews, setInterviews] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState("Upcoming")
  const [search, setSearch] = useState("")

  // Reschedule Modal State
  const [rescheduleData, setRescheduleData] = useState<{ id: number, panel_id: number, date: string, start_time: string } | null>(null)
  const [rescheduleError, setRescheduleError] = useState("")
  const [rescheduling, setRescheduling] = useState(false)

  useEffect(() => {
    fetchInterviews()
  }, [])

  const fetchInterviews = async () => {
    try {
      const res = await fetchApi(`/api/interviews`)
      const data = await res.json()
      setInterviews(data.interviews || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const formatTime = (dateStr: string) => {
    return new Date(dateStr).toLocaleTimeString("en-US", { timeZone: "Asia/Kolkata", hour: "2-digit", minute: "2-digit" })
  }

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("en-US", { timeZone: "Asia/Kolkata", month: "short", day: "numeric", year: "numeric" })
  }

  const isToday = (dateStr: string) => {
    const d = new Date(dateStr)
    const today = new Date()
    return d.getDate() === today.getDate() &&
      d.getMonth() === today.getMonth() &&
      d.getFullYear() === today.getFullYear()
  }

  const isUpcoming = (dateStr: string) => {
    return new Date(dateStr) > new Date()
  }

  const [dateFilter, setDateFilter] = useState("")
  const [panelFilter, setPanelFilter] = useState("ALL")

  const uniquePanels = Array.from(new Set(interviews.map(inv => inv.panel?.name))).filter(Boolean)

  const filteredInterviews = interviews.filter(inv => {
    let tabMatch = false
    if (activeTab === "Upcoming") tabMatch = isUpcoming(inv.start_time) && inv.status !== "CANCELLED"
    if (activeTab === "Today") tabMatch = isToday(inv.start_time)
    if (activeTab === "Completed") tabMatch = inv.status === "COMPLETED" || inv.status === "FEEDBACK_SUBMITTED"
    if (activeTab === "Cancelled") tabMatch = inv.status === "CANCELLED"

    const searchMatch = inv.candidate?.name.toLowerCase().includes(search.toLowerCase())

    let dateMatch = true
    if (dateFilter) {
      const invDate = new Date(inv.date).toISOString().split('T')[0]
      dateMatch = invDate === dateFilter
    }

    let panelMatch = true
    if (panelFilter !== "ALL") {
      panelMatch = inv.panel?.name === panelFilter
    }

    return tabMatch && searchMatch && dateMatch && panelMatch
  })

  const [viewMode, setViewMode] = useState<"LIST" | "CALENDAR">("LIST")
  const currentDate = new Date()
  const currentMonth = currentDate.getMonth()
  const currentYear = currentDate.getFullYear()
  
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate()
  const firstDayOfMonth = new Date(currentYear, currentMonth, 1).getDay()
  
  const calendarDays = Array.from({ length: daysInMonth }, (_, i) => i + 1)
  const emptyDays = Array.from({ length: firstDayOfMonth }, (_, i) => i)

  const handleReschedule = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!rescheduleData) return
    setRescheduling(true)
    setRescheduleError("")

    try {
      const res = await fetchApi(`/api/interviews/${rescheduleData.id}`, {  
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          date: rescheduleData.date,
          start_time: rescheduleData.start_time
        })
      })
      
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || "Rescheduling failed")
      
      setRescheduleData(null)
      fetchInterviews()
    } catch (err: any) {
      setRescheduleError(err.message)
    } finally {
      setRescheduling(false)
    }
  }

  const generateSlots = () => {
    const slots = []
    for (let h = 10; h <= 17; h++) {
      for (let m = 0; m < 60; m += 10) {
        slots.push(`${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`)
      }
    }
    return slots
  }

  const allSlots = generateSlots()

  const getOccupiedSlots = () => {
    if (!rescheduleData || !rescheduleData.date) return new Set()
    
    const occupied = new Set()
    interviews.forEach(inv => {
      if (inv.id === rescheduleData.id) return
      
      if (inv.panel_id === rescheduleData.panel_id) {
        const invDate = new Date(inv.date).toISOString().split('T')[0]
        if (invDate === rescheduleData.date) {
          const invTime = new Date(inv.start_time).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' })
          occupied.add(invTime)
        }
      }
    })
    return occupied
  }

  const occupiedSlots = getOccupiedSlots()

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out] pb-10">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>Meetings Module</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            Meetings Dashboard
          </h1>
        </div>
        <div className="flex gap-4 items-center">
          <div className="flex bg-[#120202] border border-[#2a0d0d] rounded-md overflow-hidden p-1">
            <button 
              onClick={() => setViewMode("LIST")}
              className={`px-4 py-2 font-mono text-[11px] uppercase tracking-widest transition-colors ${viewMode === "LIST" ? "bg-[#ac120c] text-[#f4ede4]" : "text-[#bfa8a2] hover:text-[#f4ede4]"}`}
            >
              List
            </button>
            <button 
              onClick={() => setViewMode("CALENDAR")}
              className={`px-4 py-2 font-mono text-[11px] uppercase tracking-widest transition-colors ${viewMode === "CALENDAR" ? "bg-[#ac120c] text-[#f4ede4]" : "text-[#bfa8a2] hover:text-[#f4ede4]"}`}
            >
              Calendar
            </button>
          </div>
          <Link href="/recruiter/meetings/schedule">
            <Button variant="cta">SCHEDULE</Button>
          </Link>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex gap-4 border-b border-[#2a0d0d] pb-2">
        {["Upcoming", "Today", "Completed", "Cancelled"].map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`pb-2 px-2 font-mono text-[13px] uppercase tracking-widest transition-all ${
              activeTab === tab 
                ? "text-[#d07d22] border-b-2 border-[#d07d22]" 
                : "text-[#bfa8a2] hover:text-[#f4ede4]"
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      <Card className="flex flex-col sm:flex-row gap-4 p-4 items-center">
        <div className="w-full sm:w-1/3">
          <Input 
            placeholder="Search candidate..." 
            value={search}
            onChange={(e: any) => setSearch(e.target.value)}
          />
        </div>
        <div className="w-full sm:w-1/3">
          <input
            type="date"
            value={dateFilter}
            onChange={(e) => setDateFilter(e.target.value)}
            className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-none font-mono text-[13px] focus:outline-none focus:border-[#d07d22] transition-colors"
          />
        </div>
        <div className="w-full sm:w-1/3">
          <select
            value={panelFilter}
            onChange={(e) => setPanelFilter(e.target.value)}
            className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-none font-mono text-[13px] focus:outline-none focus:border-[#d07d22] transition-colors"
          >
            <option value="ALL">All Panels</option>
            {uniquePanels.map((p: any) => (
              <option key={p} value={p}>{p}</option>
            ))}
          </select>
        </div>
      </Card>

      {viewMode === "LIST" ? (
        <Card className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse min-w-[800px]">
              <thead>
                <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                  <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">CANDIDATE</th>
                  <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">PANEL</th>
                  <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">DATE & TIME</th>
                  <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">STATUS</th>
                  <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">MEETING</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#2a0d0d]">
                {loading ? (
                  <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">LOADING DATA...</td></tr>
                ) : filteredInterviews.length === 0 ? (
                  <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">NO INTERVIEWS MATCH THIS CRITERIA.</td></tr>
                ) : (
                  filteredInterviews.map((interview) => (
                    <tr key={interview.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                      <td className="p-4">
                        <p className="text-[#f4ede4] font-medium">{interview.candidate?.name}</p>
                        <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">{interview.candidate?.department}</p>
                      </td>
                      <td className="p-4 text-[#f4ede4] font-medium">
                        {interview.panel?.name}
                      </td>
                      <td className="p-4">
                        <p className="text-[#f4ede4] font-medium">{formatDate(interview.date)}</p>
                        <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">
                          {formatTime(interview.start_time)}
                        </p>
                      </td>
                      <td className="p-4">
                        <StatusPill status={interview.status.toLowerCase().includes('cancel') ? 'rejected' : 'active'}>
                          {interview.status}
                        </StatusPill>
                      </td>
                      <td className="p-4 flex gap-2 items-center flex-wrap">
                        {interview.meeting_link ? (
                          <a href={interview.meeting_link} target="_blank" className="text-[#2e7d32] font-medium text-sm hover:underline">
                            JOIN
                          </a>
                        ) : (
                          <span className="text-[#bfa8a2] font-mono text-[11px]">N/A</span>
                        )}
                        {interview.status !== "CANCELLED" && interview.status !== "COMPLETED" && (
                          <>
                            <button 
                              onClick={() => setRescheduleData({ 
                                id: interview.id, 
                                panel_id: interview.panel_id,
                                date: new Date(interview.date).toISOString().split('T')[0],
                                start_time: new Date(interview.start_time).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' }) 
                              })}
                              className="text-[#d07d22] font-mono text-[10px] ml-4 hover:underline uppercase"
                            >
                              RESCHEDULE
                            </button>
                            <button 
                              onClick={async () => {
                                if(confirm("Cancel this interview?")) {
                                  await fetchApi(`/api/interviews/${interview.id}`, {   method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status: "CANCELLED" }) })
                                  fetchInterviews()
                                }
                              }}
                              className="text-[#ac120c] font-mono text-[10px] ml-2 hover:underline uppercase"
                            >
                              CANCEL
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      ) : (
        <Card className="p-6">
          <div className="grid grid-cols-7 gap-2 mb-4">
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
              <div key={day} className="text-center font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">{day}</div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-2">
            {emptyDays.map(empty => (
              <div key={`empty-${empty}`} className="min-h-[100px] bg-[#0a0202]/50 border border-[#2a0d0d]/30 rounded-md"></div>
            ))}
            {calendarDays.map(day => {
              const dayInterviews = filteredInterviews.filter(inv => {
                const d = new Date(inv.date)
                return d.getDate() === day && d.getMonth() === currentMonth && d.getFullYear() === currentYear
              })

              return (
                <div key={day} className="min-h-[100px] bg-[#120202] border border-[#2a0d0d] rounded-md p-2 flex flex-col gap-1 transition-colors hover:border-[#d07d22]/50">
                  <span className="font-mono text-[12px] text-[#f4ede4]">{day}</span>
                  <div className="flex flex-col gap-1 overflow-y-auto max-h-[80px] custom-scrollbar">
                    {dayInterviews.map(inv => (
                      <div key={inv.id} className="text-[10px] font-mono bg-[#ac120c]/20 text-[#f4ede4] p-1 rounded-sm whitespace-nowrap overflow-hidden text-ellipsis border border-[#ac120c]/30">
                        {formatTime(inv.start_time)} {inv.candidate?.name}
                      </div>
                    ))}
                  </div>
                </div>
              )
            })}
          </div>
        </Card>
      )}

      <Modal isOpen={!!rescheduleData} onClose={() => setRescheduleData(null)}>
        <h2 className="font-display font-bold text-[24px] text-[#f4ede4] mb-6">Reschedule Interview</h2>
        {rescheduleError && (
          <div className="bg-[#ac120c]/10 border border-[#ac120c]/50 text-[#ac120c] p-3 rounded-lg text-sm font-medium mb-4">
            {rescheduleError}
          </div>
        )}
        <form onSubmit={handleReschedule} className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Date</label>
            <Input 
              type="date"
              value={rescheduleData?.date || ""}
              onChange={(e: any) => setRescheduleData(prev => prev ? { ...prev, date: e.target.value, start_time: "" } : null)}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Time Slot (10 mins)</label>
            <select
              value={rescheduleData?.start_time || ""}
              onChange={(e: any) => setRescheduleData(prev => prev ? { ...prev, start_time: e.target.value } : null)}
              className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono focus:border-[#d07d22] outline-none"
              required
              disabled={!rescheduleData?.date}
            >
              <option value="" disabled>Select Slot</option>
              {allSlots.map(slot => {
                const isOccupied = occupiedSlots.has(slot)
                return (
                  <option key={slot} value={slot} disabled={isOccupied}>
                    {slot} {isOccupied ? "(Occupied)" : "(Available)"}
                  </option>
                )
              })}
            </select>
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button type="button" variant="ghost" onClick={() => setRescheduleData(null)}>CANCEL</Button>
            <Button type="submit" variant="cta" disabled={rescheduling}>
              {rescheduling ? "SAVING..." : "CONFIRM"}
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"

import React, { useState, useEffect, Suspense } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { Input } from "@/components/ui/Input"
import { Button } from "@/components/ui/Button"

function ScheduleForm() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const initialCandidateId = searchParams.get("candidate") || ""

  const [panels, setPanels] = useState<any[]>([])
  const [candidates, setCandidates] = useState<any[]>([])
  const [existingInterviews, setExistingInterviews] = useState<any[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")

  const [formData, setFormData] = useState({
    candidate_id: initialCandidateId ? parseInt(initialCandidateId) : "",
    application_id: "",
    panel_id: "",
    date: "",
    start_time: "",
    meeting_link: ""
  })

  useEffect(() => {
    Promise.all([
      fetchApi(`/api/panels`).then(r => r.json()),
      fetchApi(`/api/candidates?status=SHORTLISTED`).then(r => r.json()),
      fetchApi(`/api/interviews`).then(r => r.json())
    ]).then(([panelData, candidateData, interviewData]) => {
      setPanels(panelData.panels || [])
      setCandidates(candidateData.candidates || [])
      setExistingInterviews(interviewData.interviews || [])
    })
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError("")

    try {
      const res = await fetchApi(`/api/interviews/schedule`, {  
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          candidate_id: Number(formData.candidate_id),
          application_id: Number(formData.application_id),
          panel_id: Number(formData.panel_id)
        })
      })
      
      const data = await res.json()
      
      if (!res.ok) {
        throw new Error(data.error || "Scheduling failed")
      }

      router.push("/recruiter/meetings")
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  // Generate 10-minute slots from 10:00 to 18:00
  const generateSlots = () => {
    const slots = []
    for (let h = 10; h <= 17; h++) {
      for (let m = 0; m < 60; m += 10) {
        const hh = h.toString().padStart(2, '0')
        const mm = m.toString().padStart(2, '0')
        slots.push(`${hh}:${mm}`)
      }
    }
    return slots
  }
  
  const allSlots = generateSlots()

  // Get occupied slots for selected panel and date
  const getOccupiedSlots = () => {
    if (!formData.panel_id || !formData.date) return new Set()
    
    const occupied = new Set()
    existingInterviews.forEach(inv => {
      if (inv.panel_id.toString() === formData.panel_id.toString()) {
        const invDate = new Date(inv.date).toISOString().split('T')[0]
        if (invDate === formData.date) {
          const invTime = new Date(inv.start_time).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' })
          occupied.add(invTime)
        }
      }
    })
    return occupied
  }

  const occupiedSlots = getOccupiedSlots()

  return (
    <Card className="p-8 max-w-2xl">
      {error && (
        <div className="bg-[#ac120c]/10 border border-[#ac120c]/50 text-[#ac120c] p-4 rounded-lg text-sm font-medium mb-6">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        <div className="flex flex-col gap-2">
          <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Candidate</label>
          <select
            value={formData.candidate_id}
            onChange={e => setFormData({ ...formData, candidate_id: e.target.value, application_id: "" })}
            className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono focus:border-[#d07d22] outline-none"
            required
          >
            <option value="" disabled>Select Shortlisted Candidate</option>
            {candidates.map(c => (
              <option key={c.id} value={c.id}>{c.name} ({c.registration_number})</option>
            ))}
          </select>
        </div>

        {formData.candidate_id && (
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Application</label>
            <select
              value={formData.application_id}
              onChange={e => setFormData({ ...formData, application_id: e.target.value })}
              className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono focus:border-[#d07d22] outline-none"
              required
            >
              <option value="" disabled>Select Application</option>
              {candidates
                .find(c => c.id === Number(formData.candidate_id))
                ?.applications?.filter((a: any) => a.status === 'SHORTLISTED' || a.status === 'FURTHER_ROUND')
                .map((a: any) => (
                  <option key={a.id} value={a.id}>Application ID: {a.id} - {a.status}</option>
                ))}
            </select>
          </div>
        )}

        <div className="flex flex-col gap-2">
          <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Interview Panel</label>
          <select
            value={formData.panel_id}
            onChange={e => setFormData({ ...formData, panel_id: e.target.value, start_time: "" })}
            className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono focus:border-[#d07d22] outline-none"
            required
          >
            <option value="" disabled>Select Panel</option>
            {panels.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Date</label>
            <Input 
              type="date"
              value={formData.date}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData({ ...formData, date: e.target.value, start_time: "" })}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Time Slot (10 mins)</label>
            <select
              value={formData.start_time}
              onChange={e => setFormData({ ...formData, start_time: e.target.value })}
              className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono focus:border-[#d07d22] outline-none"
              required
              disabled={!formData.date || !formData.panel_id}
            >
              <option value="" disabled>
                {!formData.date || !formData.panel_id ? "Select Panel & Date first" : "Select Slot"}
              </option>
              {allSlots.map(slot => {
                const isOccupied = occupiedSlots.has(slot)
                return (
                  <option key={slot} value={slot} disabled={isOccupied}>
                    {slot} {isOccupied ? "(Occupied)" : "(Available)"}
                  </option>
                )
              })}
            </select>
          </div>
        </div>

        <div className="flex flex-col gap-2">
          <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Meeting Link</label>
          <Input 
            type="url"
            placeholder="https://meet.google.com/..."
            value={formData.meeting_link}
            onChange={e => setFormData({ ...formData, meeting_link: e.target.value })}
            required
          />
        </div>

        <div className="mt-4 flex justify-end">
          <Button type="submit" variant="cta" disabled={loading} className="w-full sm:w-auto">
            {loading ? "SCHEDULING..." : "SCHEDULE INTERVIEW"}
          </Button>
        </div>
      </form>
    </Card>
  )
}

export default function SchedulePage() {
  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out] pb-10">
      <header className="flex flex-col gap-2">
        <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
          <DiamondIcon />
          <span>Meetings Module</span>
        </div>
        <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
          Schedule Interview
        </h1>
      </header>

      <Suspense fallback={<div className="text-[#bfa8a2] font-mono p-8">LOADING...</div>}>
        <ScheduleForm />
      </Suspense>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { useRouter, useParams } from "next/navigation"
import { Card } from "@/components/ui/Card"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { DiamondIcon } from "@/components/ui/Icons"

export default function DynamicRecruitmentPage() {
  const router = useRouter()
  const params = useParams()
  const [formId, setFormId] = useState<number>(1)
  const [questions, setQuestions] = useState<any[]>([])
  const [formInfo, setFormInfo] = useState<any>(null)
  
  const [formData, setFormData] = useState<Record<string, string>>({
    name: "",
    email: "",
    phone: "",
    registration_number: "",
    department: "CSE",
    resume_url: "",
  })
  
  const [dynamicAnswers, setDynamicAnswers] = useState<Record<string, string>>({})
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState("")

  useEffect(() => {
    if (params?.formId) {
      setFormId(parseInt(params.formId as string, 10))
    }
  }, [params])

  useEffect(() => {
    if (formId) {
      fetchQuestions()
    }
  }, [formId])

  const fetchQuestions = async () => {
    try {
      const res = await fetchApi(`/api/forms/${formId}`)
      if (!res.ok) throw new Error("Form not found")
      const data = await res.json()
      
      if (data.form?.status !== "PUBLISHED") {
        throw new Error("This recruitment form is not currently open for applications.")
      }

      setFormInfo(data.form)
      setQuestions(data.form?.questions || [])
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const handleBaseChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value })
  }

  const handleDynamicChange = (questionId: string, value: string | string[]) => {
    setDynamicAnswers({ ...dynamicAnswers, [questionId]: value as string })
  }

  const handleCheckboxChange = (questionId: string, option: string, checked: boolean) => {
    const current = (dynamicAnswers[questionId] as unknown as string[]) || []
    if (checked) {
      handleDynamicChange(questionId, [...current, option] as unknown as string)
    } else {
      handleDynamicChange(questionId, current.filter(o => o !== option) as unknown as string)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError("")

    try {
      const payload = {
        ...formData,
        form_id: formId,
        answers: dynamicAnswers
      }

      const res = await fetchApi(`/api/applications`, {  
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      })

      const data = await res.json()

      if (!res.ok) {
        throw new Error(data.error || "Failed to submit application")
      }

      router.push("/application-success")
    } catch (err: any) {
      setError(err.message)
    } finally {
      setSubmitting(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0a0202] flex items-center justify-center">
        <DiamondIcon className="text-[#ac120c] animate-pulse w-10 h-10" />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#0a0202] flex items-center justify-center p-6 py-12">
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/4 w-[500px] h-[500px] bg-[#ac120c] opacity-[0.03] blur-[120px] rounded-full mix-blend-screen" />
        <div className="absolute bottom-0 right-1/4 w-[600px] h-[600px] bg-[#d07d22] opacity-[0.02] blur-[150px] rounded-full mix-blend-screen" />
      </div>

      <div className="w-full max-w-[700px] animate-[rise_0.6s_cubic-bezier(0.2,0.8,0.2,1)] relative z-10">
        <div className="flex flex-col items-center mb-10 gap-4">
          <div className="w-16 h-16 rounded-full bg-[#120202] border border-[#ac120c]/30 flex items-center justify-center shadow-[0_0_40px_rgba(172,18,12,0.2)] relative">
            <DiamondIcon className="text-[#ac120c] w-6 h-6 animate-[pulse-scale_2s_infinite]" />
          </div>
          <div className="text-center">
            <h1 className="font-display font-black text-[24px] sm:text-[32px] text-[#f4ede4] tracking-wide uppercase">
              {formInfo?.title || `Recruitment Form #${formId}`}
            </h1>
            <p className="font-mono text-[#bfa8a2] text-[12px] uppercase tracking-[0.1em] mt-2">
              {formInfo?.description || "System Initiation"}
            </p>
          </div>
        </div>

        <Card className="p-8 sm:p-10 bg-[#120202]/80 backdrop-blur-md border border-[#2a0d0d] shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-[2px] bg-gradient-to-r from-transparent via-[#ac120c] to-transparent opacity-50" />
          
          <form onSubmit={handleSubmit} className="flex flex-col gap-8">
            {error && (
              <div className="bg-[#ac120c]/10 border border-[#ac120c]/50 text-[#f4ede4] p-4 rounded-sm text-sm font-mono tracking-wide">
                <span className="text-[#ac120c] font-bold mr-2">ERR:</span> {error}
              </div>
            )}
            
            <div className="flex flex-col gap-6">
              <h3 className="font-display text-[#d07d22] text-sm uppercase tracking-widest border-b border-[#2a0d0d] pb-2">Base Identity</h3>
              
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="flex flex-col gap-2">
                  <label className="font-mono text-[10px] text-[#bfa8a2] uppercase tracking-[0.2em]">Full Name</label>
                  <Input name="name" type="text" value={formData.name} onChange={handleBaseChange} required />
                </div>
                <div className="flex flex-col gap-2">
                  <label className="font-mono text-[10px] text-[#bfa8a2] uppercase tracking-[0.2em]">Registration No.</label>
                  <Input name="registration_number" type="text" value={formData.registration_number} onChange={handleBaseChange} required />
                </div>
                <div className="flex flex-col gap-2">
                  <label className="font-mono text-[10px] text-[#bfa8a2] uppercase tracking-[0.2em]">Email Address</label>
                  <Input name="email" type="email" value={formData.email} onChange={handleBaseChange} required />
                </div>
                <div className="flex flex-col gap-2">
                  <label className="font-mono text-[10px] text-[#bfa8a2] uppercase tracking-[0.2em]">Phone Number</label>
                  <Input name="phone" type="tel" value={formData.phone} onChange={handleBaseChange} required />
                </div>
                <div className="flex flex-col gap-2 sm:col-span-2">
                  <label className="font-mono text-[10px] text-[#bfa8a2] uppercase tracking-[0.2em]">Target Department</label>
                  <select
                    name="department"
                    value={formData.department}
                    onChange={handleBaseChange}
                    className="w-full bg-[#1a0606] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-none font-mono text-[13px] focus:outline-none focus:border-[#d07d22] transition-colors"
                    required
                  >
                    <option value="CSE">Computer Science</option>
                    <option value="ECE">Electronics</option>
                    <option value="DESIGN">Design</option>
                    <option value="MANAGEMENT">Management</option>
                  </select>
                </div>
                <div className="flex flex-col gap-2 sm:col-span-2">
                  <label className="font-mono text-[10px] text-[#bfa8a2] uppercase tracking-[0.2em]">Resume Link</label>
                  <Input name="resume_url" type="url" value={formData.resume_url} onChange={handleBaseChange} placeholder="https://..." required />
                </div>
              </div>
            </div>

            {questions.length > 0 && (
              <div className="flex flex-col gap-6">
                <h3 className="font-display text-[#d07d22] text-sm uppercase tracking-widest border-b border-[#2a0d0d] pb-2">Technical Evaluation</h3>
                
                {questions.map((q) => (
                  <div key={q.id} className="flex flex-col gap-2">
                    <label className="font-mono text-[10px] text-[#bfa8a2] uppercase tracking-[0.2em]">
                      {q.question} {q.required && <span className="text-[#ac120c]">*</span>}
                    </label>
                    
                    {q.type === "TEXT" && (
                      <Input 
                        value={dynamicAnswers[q.id] || ""} 
                        onChange={(e) => handleDynamicChange(q.id.toString(), e.target.value)} 
                        required={q.required} 
                      />
                    )}
                    
                    {q.type === "PARAGRAPH" && (
                      <textarea 
                        value={dynamicAnswers[q.id] || ""} 
                        onChange={(e) => handleDynamicChange(q.id.toString(), e.target.value)} 
                        required={q.required}
                        className="w-full bg-[#1a0606] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-none font-mono text-[13px] focus:outline-none focus:border-[#d07d22] transition-colors min-h-[100px]"
                      />
                    )}

                    {q.type === "RADIO" && q.options && (
                      <div className="flex flex-col gap-2 mt-2">
                        {q.options.map((opt: string, idx: number) => (
                          <label key={idx} className="flex items-center gap-3 cursor-pointer group">
                            <input 
                              type="radio" 
                              name={`question_${q.id}`} 
                              value={opt}
                              checked={dynamicAnswers[q.id] === opt}
                              onChange={() => handleDynamicChange(q.id.toString(), opt)}
                              required={q.required && !dynamicAnswers[q.id]}
                              className="appearance-none w-4 h-4 rounded-full border border-[#d07d22] checked:bg-[#ac120c] transition-all"
                            />
                            <span className="font-mono text-[12px] text-[#bfa8a2] group-hover:text-[#f4ede4] transition-colors">{opt}</span>
                          </label>
                        ))}
                      </div>
                    )}

                    {q.type === "DROPDOWN" && q.options && (
                      <select
                        value={dynamicAnswers[q.id] || ""}
                        onChange={(e) => handleDynamicChange(q.id.toString(), e.target.value)}
                        required={q.required}
                        className="w-full bg-[#1a0606] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-none font-mono text-[13px] focus:outline-none focus:border-[#d07d22] transition-colors"
                      >
                        <option value="" disabled>Select an option...</option>
                        {q.options.map((opt: string, idx: number) => (
                          <option key={idx} value={opt}>{opt}</option>
                        ))}
                      </select>
                    )}

                    {q.type === "CHECKBOX" && q.options && (
                      <div className="flex flex-col gap-2 mt-2">
                        {q.options.map((opt: string, idx: number) => {
                          const currentAnswers = (dynamicAnswers[q.id] as unknown as string[]) || [];
                          return (
                            <label key={idx} className="flex items-center gap-3 cursor-pointer group">
                              <input 
                                type="checkbox" 
                                name={`question_${q.id}`} 
                                value={opt}
                                checked={currentAnswers.includes(opt)}
                                onChange={(e) => handleCheckboxChange(q.id.toString(), opt, e.target.checked)}
                                className="appearance-none w-4 h-4 border border-[#d07d22] checked:bg-[#ac120c] transition-all rounded-sm"
                              />
                              <span className="font-mono text-[12px] text-[#bfa8a2] group-hover:text-[#f4ede4] transition-colors">{opt}</span>
                            </label>
                          )
                        })}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}

            <div className="mt-8 pt-6 border-t border-[#2a0d0d] flex justify-end">
              <Button type="submit" disabled={submitting} className="w-full sm:w-auto px-10 bg-[#ac120c] hover:bg-[#8a0e0a] text-[#f4ede4] font-display uppercase tracking-widest text-sm h-12 rounded-none border-none relative overflow-hidden group">
                <span className="relative z-10">{submitting ? "UPLOADING..." : "TRANSMIT"}</span>
                <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:animate-[shimmer_1s_infinite]" />
              </Button>
            </div>
          </form>
        </Card>
      </div>
    </div>
  )
}

"use client"

import React, { useMemo } from "react"
import { useReducedMotion } from "@/lib/hooks/useReducedMotion"

function generateStars(count: number) {
  let shadow = ""
  for (let i = 0; i < count; i++) {
    const x = Math.floor(Math.random() * 2000)
    const y = Math.floor(Math.random() * 2000)
    shadow += `${x}px ${y}px #FFF${i === count - 1 ? "" : ", "}`
  }
  return shadow
}

export function BackgroundEffects() {
  const prefersReducedMotion = useReducedMotion()
  
  // Memoize static box-shadows so they don't re-render and cause hydration mismatches
  const { stars1, stars2 } = useMemo(() => {
    // Only generate stars on client to avoid hydration mismatch, or provide a deterministic seed
    // For simplicity, we just use random and suppress hydration warnings or render on mount
    return {
      stars1: generateStars(200),
      stars2: generateStars(100)
    }
  }, [])

  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => setMounted(true), [])

  return (
    <div className="fixed inset-0 z-[-1] pointer-events-none overflow-hidden bg-[#020000]">
      
      {/* CSS Starfield */}
      {mounted && !prefersReducedMotion && (
        <div className="absolute inset-0 opacity-40">
          <div 
            className="w-[1px] h-[1px] bg-transparent animate-stars"
            style={{ boxShadow: stars1 }}
          />
          <div 
            className="w-[2px] h-[2px] bg-transparent animate-stars-slow opacity-60"
            style={{ boxShadow: stars2 }}
          />
        </div>
      )}

      {/* Radial glow top left */}
      <div 
        className="absolute w-[800px] h-[800px] rounded-full opacity-30 mix-blend-screen animate-pulse-slow"
        style={{
          top: "-300px",
          left: "-200px",
          background: "radial-gradient(circle, rgba(172, 18, 12, 0.4) 0%, transparent 70%)"
        }}
      />
      
      {/* Radial glow bottom right */}
      <div 
        className="absolute w-[900px] h-[900px] rounded-full opacity-25 mix-blend-screen animate-pulse-slow"
        style={{
          bottom: "-400px",
          right: "-300px",
          background: "radial-gradient(circle, rgba(208, 125, 34, 0.25) 0%, transparent 65%)",
          animationDelay: "1s"
        }}
      />
      
      {/* Subtle Grid overlay */}
      <div 
        className="absolute inset-0 opacity-[0.03]"
        style={{
          backgroundImage: "linear-gradient(rgba(255,255,255,1) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,1) 1px, transparent 1px)",
          backgroundSize: "60px 60px"
        }}
      />
    </div>
  )
}

